"""Exercise the production Root metadata/focus lease, including partial focus failures and retries."""
from pathlib import Path
import argparse
import runpy
import subprocess
import tempfile

PASTE = runpy.run_path(str(Path(__file__).with_name("test-atomic-workbench-paste.py")))
SUPPORT = PASTE["SUPPORT"]
# Root's metadata/focus host neither constructs the app A11y service nor performs
# extraction. Drop its unused app-only doubles instead of fabricating a service.
SOURCES = {name:text for name,text in PASTE["SOURCES"].items() if not name.startswith('ls/augment/com/AtomicWorkbenchExtraction')}
PRODUCTION = PASTE["MODELS"][:-1] + ["AtomicWorkbenchPasteHost.java"]

TEST = r'''package ls.augment.com;
import android.os.*;import java.util.*;
public class TestPasteHost {
 static int cases,checks;static void check(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}interface Case{void run()throws Exception;}static void test(String n,Case c)throws Exception{SystemClock.time=1000;c.run();cases++;System.out.println("PASS paste host: "+n);}
 static AtomicWorkbenchPasteRequest request(){return request("0123456789abcdef0123456789abcdef",1000,6000);}
 static AtomicWorkbenchPasteRequest request(String id,long created,long deadline){return new AtomicWorkbenchPasteRequest(id,7,2,4,0,88,"DuoAtomic-10055-w0-12345678-1234-1234-1234-123456789abc","virtual:root,88",0,10055,10101,42,"example.editor","source1",3,"ORIGINAL PRIVATE TEXT MUST NEVER ENTER ROOT",created,deadline);}
 static Bundle state(int window){Bundle b=new Bundle();b.putBoolean("success",true);b.putString("state","active");b.putBoolean("recovery_pending",false);b.putBoolean("native_home",false);b.putBoolean("home_only",false);b.putInt("window_id",window);b.putInt("display_id",88+window);b.putString("display_name","DuoAtomic-10055-w"+window+"-12345678-1234-1234-1234-123456789abc");b.putString("display_unique_id","virtual:root,"+(88+window));b.putInt("user_id",0);b.putInt("target_uid",10101+window);b.putInt("task_id",42+window);b.putString("package",window==0?"example.editor":"other.editor");return b;}
 static final class Fixture implements AtomicWorkbenchPasteHost.Workspace {
  final Map<Integer,Bundle> states=new HashMap<>();final List<Integer> focuses=new ArrayList<>();int active=1,queries;long revision=10;boolean session=true,sessionThrows,focusFail,focusThrow,partialFocus,queryFail,revisionFrozen;String connection="2".repeat(32),queryFailure;Runnable focusHook,queryHook,snapshotHook,sessionHook;
  final AtomicWorkbenchPasteHost host=new AtomicWorkbenchPasteHost(10055,0,7,2,SystemClock::elapsedRealtime,this);
  Fixture(){states.put(0,state(0));states.put(1,state(1));}
  public Bundle windowState(int id){if(snapshotHook!=null)snapshotHook.run();return states.get(id)==null?null:new Bundle(states.get(id));}
  public int activeInputWindow(){return active;}public long inputRevision(){return revision;}
  public Bundle focusInputOnly(int id)throws Exception{focuses.add(id);if(!revisionFrozen)revision++;if(!focusFail||partialFocus)active=id;if(focusHook!=null)focusHook.run();if(focusThrow)throw new Exception("focus result lost");Bundle b=new Bundle();b.putBoolean("success",!focusFail);return b;}
  public boolean sessionCurrent(long session,long reset)throws Exception{check(session==7&&reset==2,"Host borrowed foreign session");if(sessionThrows)throw new Exception();if(sessionHook!=null)sessionHook.run();return this.session;}
  public AtomicWorkbenchEditorEvidence queryEvidence(AtomicWorkbenchPasteRequest r)throws Exception{queries++;check(r.text.equals("x"),"original body entered Root metadata path");if(queryHook!=null)queryHook.run();if(queryFailure!=null)throw new IllegalStateException(queryFailure);if(queryFail)throw new Exception();return new AtomicWorkbenchEditorEvidence(r.windowId,r.displayId,r.displayName,r.displayUniqueId,r.userId,r.moduleUid,r.targetUid,r.taskId,r.packageName,71,"1".repeat(32),connection,1,0,SystemClock.time);}
  Bundle prepare(){return host.prepare(request().metadata());}Bundle release(){return host.release(request().metadata());}
 }
 public static void main(String[] args)throws Exception{
  test("metadata exact 18 typed keys excludes original text",()->{Bundle m=request().metadata();check(m.size()==18&&!m.toString().contains("ORIGINAL")&&!m.containsKey("text"),"metadata leaked payload");Fixture f=new Fixture();Bundle p=f.prepare();check(p.getBoolean("success")&&p.getBundle("evidence")!=null&&f.active==0&&f.focuses.equals(List.of(0)),"target focus not prepared");check(p.getBoolean("restore_required")&&!p.getBoolean("cleanup_pending"),"active lease mislabeled failed cleanup");Bundle done=f.release();check(done.getBoolean("success")&&done.getBoolean("focus_restored")&&f.active==1&&f.focuses.equals(List.of(0,1))&&!f.host.hasCleanupResponsibility(),"prior focus not restored");});
  test("same active editor never receives focus pulse",()->{Fixture f=new Fixture();f.active=0;check(f.prepare().getBoolean("success")&&f.focuses.isEmpty(),"current editor pulsed");check(f.release().getBoolean("focus_restored")&&f.focuses.isEmpty(),"release pulsed current editor");});
  test("physical host restores through -1 without moving HOME",()->{Fixture f=new Fixture();f.active=-1;check(f.prepare().getBoolean("success"),"side editor from host not prepared");check(f.release().getBoolean("focus_restored")&&f.active==-1&&f.focuses.equals(List.of(0,-1)),"host focus not conditionally restored");});
  test("native HOME cannot be a paste target but prior HOME VD can be restored",()->{Fixture f=new Fixture();f.states.get(0).putBoolean("native_home",true);check(!f.prepare().getBoolean("success")&&f.focuses.isEmpty(),"HOME editor target accepted");Fixture g=new Fixture();g.states.get(1).putBoolean("native_home",true);g.states.get(1).putBoolean("home_only",true);check(g.prepare().getBoolean("success")&&g.release().getBoolean("focus_restored"),"prior native HOME display not restorable");});
  test("duplicate prepare does not repeat focus and terminal ID cannot run again",()->{Fixture f=new Fixture();Bundle first=f.prepare();Bundle repeat=f.prepare();check(first.getBoolean("success")&&repeat.getBoolean("success")&&f.focuses.size()==1,"duplicate prepare focused twice");f.release();check(!f.prepare().getBoolean("success")&&f.focuses.size()==2,"released ID reactivated");check(f.release().getBoolean("success")&&f.focuses.size()==2,"duplicate release moved focus");});
  test("single active lease rejects a competing drop and metadata ID mutation",()->{Fixture f=new Fixture();check(f.prepare().getBoolean("success"),"fixture not ready");Bundle other=request("a".repeat(32),1000,6000).metadata();check(!f.host.prepare(other).getBoolean("success")&&f.focuses.size()==1,"competing lease moved focus");Bundle changed=request().metadata();changed.putLong("epoch",5);check(!f.host.prepare(changed).getBoolean("success")&&!f.host.release(changed).getBoolean("success")&&f.host.hasCleanupResponsibility(),"changed identity took/released old lease");});
  for(String key:new String[]{"schema","id","session","reset","epoch","window","display","name","unique","user","module_uid","target_uid","task","package","source_id","source_revision","created","deadline"})test("missing/wrong metadata type rejected: "+key,()->{Fixture f=new Fixture();Bundle missing=request().metadata();missing.remove(key);check(!f.host.prepare(missing).getBoolean("success")&&f.focuses.isEmpty(),"missing metadata accepted");Bundle wrong=request().metadata();wrong.put(key,new Object());check(!f.host.prepare(wrong).getBoolean("success")&&f.focuses.isEmpty(),"foreign Parcelable/Binder-shaped metadata accepted");});
  test("unknown fields and actual payload/Binder graph are forbidden",()->{Fixture f=new Fixture();Bundle b=request().metadata();b.putString("text","private");check(!f.host.prepare(b).getBoolean("success")&&f.focuses.isEmpty(),"unexpected payload field accepted");b=request().metadata();b.put("endpoint",new Object());check(!f.host.prepare(b).getBoolean("success")&&f.focuses.isEmpty(),"foreign endpoint graph accepted");});
  for(String key:new String[]{"success","state","recovery_pending","window_id","display_id","display_name","display_unique_id","task_id","target_uid","user_id","package","home_only"})test("fresh target status rejects drift/unknown: "+key,()->{Fixture f=new Fixture();Bundle b=f.states.get(0);switch(key){case "success":b.putBoolean(key,false);break;case "state":b.putString(key,"launching");break;case "recovery_pending":b.putBoolean(key,true);break;case "display_name":case "display_unique_id":case "package":b.putString(key,"different");break;case "home_only":b.putBoolean(key,true);break;default:b.putInt(key,b.getInt(key)+1);break;}check(!f.prepare().getBoolean("success")&&f.focuses.isEmpty(),"stale/foreign target accepted");});
  test("Provider reset before prepare never borrows current session",()->{Fixture f=new Fixture();f.session=false;check(!f.prepare().getBoolean("success")&&f.focuses.isEmpty(),"ended Root session focused task");});
  test("partial focus error retains responsibility until explicit cleanup",()->{Fixture f=new Fixture();f.focusFail=true;f.partialFocus=true;check(!f.prepare().getBoolean("success")&&f.active==0&&f.host.hasCleanupResponsibility(),"partial focus responsibility lost");f.focusFail=false;check(f.release().getBoolean("focus_restored")&&f.active==1&&!f.host.hasCleanupResponsibility(),"partial focus not recovered");});
  test("focus exception after change still releases the recorded prior",()->{Fixture f=new Fixture();f.focusThrow=true;check(!f.prepare().getBoolean("success")&&f.active==0&&f.host.hasCleanupResponsibility(),"thrown focus lost prior lease");f.focusThrow=false;check(f.release().getBoolean("focus_restored")&&f.active==1,"lost focus reply prevented cleanup");});
  test("prepare evidence failure does not discard changed focus",()->{Fixture f=new Fixture();f.queryFail=true;check(!f.prepare().getBoolean("success")&&f.host.hasCleanupResponsibility(),"query failure discarded focus lease");check(f.release().getBoolean("focus_restored")&&f.active==1,"evidence failure leaked focus");});
  test("restore failure survives maintain retry without reopening editing",()->{Fixture f=new Fixture();Bundle p=f.prepare();f.focusFail=true;Bundle failed=f.release();check(!failed.getBoolean("success")&&failed.getBoolean("cleanup_pending")&&f.host.hasCleanupResponsibility(),"restore failure silently cleared lease");check(!f.host.validate(request().metadata(),p.getBundle("evidence")).getBoolean("success"),"ending lease reopened editing");f.focusFail=false;check(f.host.maintain().getBoolean("focus_restored")&&f.active==1&&!f.host.hasCleanupResponsibility(),"maintain did not retry failed restore");});
  test("expiry triggers metadata cleanup but never grants a new editing deadline",()->{Fixture f=new Fixture();Bundle p=f.prepare();SystemClock.time=6000;check(!f.host.validate(request().metadata(),p.getBundle("evidence")).getBoolean("success"),"expired lease validated");check(f.host.maintain().getBoolean("focus_restored")&&f.active==1,"expired lease not restored");check(!f.prepare().getBoolean("success")&&f.focuses.size()==2,"expired metadata replayed focus");});
  test("new touch/focus revision prevents restoring an old window",()->{Fixture f=new Fixture();f.prepare();f.revision++;check(f.release().getString("reason").equals("newer_input_preserved")&&f.active==0&&f.focuses.equals(List.of(0)),"newer input lost focus to old lease");});
  test("different current input window also revokes old restore right",()->{Fixture f=new Fixture();f.prepare();f.active=-1;check(f.release().getString("reason").equals("newer_input_preserved")&&f.focuses.size()==1,"another current window was overridden");});
  test("prior and target VD reuse never restores recycled slot",()->{Fixture f=new Fixture();f.prepare();f.states.get(1).putString("display_unique_id","recycled");check(!f.release().getBoolean("focus_restored")&&f.focuses.size()==1&&!f.host.hasCleanupResponsibility(),"recycled prior display got focus");Fixture g=new Fixture();g.prepare();g.states.get(0).putString("display_unique_id","recycled");check(!g.release().getBoolean("focus_restored")&&g.focuses.size()==1,"recycled target borrowed restore right");});
  test("unknown prior snapshot preserves cleanup then retries only when fresh",()->{Fixture f=new Fixture();f.prepare();f.states.get(1).putBoolean("success",false);check(!f.release().getBoolean("success")&&f.host.hasCleanupResponsibility()&&f.focuses.size()==1,"unknown cached prior snapshot restored");f.states.get(1).putBoolean("success",true);check(f.host.maintain().getBoolean("focus_restored")&&f.active==1,"healthy prior snapshot could not recover");});
  test("reset between prepare and release never focuses through new session",()->{Fixture f=new Fixture();f.prepare();f.session=false;Bundle release=f.release();check(release.getBoolean("success")&&!release.getBoolean("focus_restored")&&!f.host.hasCleanupResponsibility()&&f.focuses.size()==1,"old lease focused new Provider session");});
  test("session unavailable keeps responsibility until resolved",()->{Fixture f=new Fixture();f.prepare();f.sessionThrows=true;check(!f.release().getBoolean("success")&&f.host.hasCleanupResponsibility(),"unknown session erased cleanup");f.sessionThrows=false;check(f.host.maintain().getBoolean("focus_restored"),"session recovery did not retry");});
  test("fresh evidence required on every validate and final state recheck",()->{Fixture f=new Fixture();Bundle p=f.prepare();check(f.host.validate(request().metadata(),p.getBundle("evidence")).getBoolean("success")&&f.queries==2,"validate reused old evidence");f.connection="3".repeat(32);check(!f.host.validate(request().metadata(),p.getBundle("evidence")).getBoolean("success"),"new same-package editor accepted old lease");Fixture g=new Fixture();g.queryHook=()->g.states.get(0).putInt("task_id",99);check(!g.prepare().getBoolean("success")&&g.host.hasCleanupResponsibility(),"task changed during query escaped final recheck");});
  test("closed host retries cleanup and never accepts another operation",()->{Fixture f=new Fixture();f.prepare();f.focusFail=true;try{f.host.close();throw new AssertionError("close silently discarded failed cleanup");}catch(IllegalStateException expected){checks++;}check(f.host.hasCleanupResponsibility()&&!f.prepare().getBoolean("success"),"closed host lost responsibility or reopened");f.focusFail=false;f.host.close();check(f.active==1&&!f.host.hasCleanupResponsibility(),"close retry not idempotent");f.host.close();});
  test("input revision must acknowledge an attempted focus before ownership is claimed",()->{Fixture f=new Fixture();f.revisionFrozen=true;check(!f.prepare().getBoolean("success")&&f.host.hasCleanupResponsibility(),"focus without revision claimed ownership");check(!f.release().getBoolean("success")&&f.host.hasCleanupResponsibility(),"unconfirmed ownership restored");f.revision++;check(f.release().getString("reason").equals("newer_input_preserved"),"later action could not retire unconfirmed lease");});
  test("exact share authorization claims once without input focus or editor access",()->{Fixture f=new Fixture();Bundle metadata=request().metadata();check(f.host.authorizeShare(metadata).getBoolean("success")&&f.focuses.isEmpty()&&f.queries==0&&f.active==1&&!f.host.hasCleanupResponsibility(),"share authorization changed input/editor");check(!f.host.authorizeShare(metadata).getBoolean("success")&&!f.host.prepare(metadata).getBoolean("success")&&f.focuses.isEmpty(),"share request ID started twice or became paste");});
  test("invalid target or session share does not consume the untouched ID",()->{Fixture f=new Fixture();Bundle metadata=request().metadata();f.states.get(0).putInt("task_id",99);check(!f.host.authorizeShare(metadata).getBoolean("success"),"stale task authorized share");f.states.get(0).putInt("task_id",42);check(f.host.authorizeShare(metadata).getBoolean("success"),"failed preflight spent share ID");Fixture g=new Fixture();g.session=false;check(!g.host.authorizeShare(metadata).getBoolean("success"),"ended session authorized share");g.session=true;check(g.host.authorizeShare(metadata).getBoolean("success"),"failed session preflight spent ID");});
  test("share refuses expired metadata, extra payload fields and an active paste lease",()->{Fixture f=new Fixture();f.prepare();check(!f.host.authorizeShare(request("a".repeat(32),1000,6000).metadata()).getBoolean("success")&&f.focuses.size()==1,"share interrupted active paste");Fixture g=new Fixture();Bundle data=request().metadata();data.putString("text","forbidden");check(!g.host.authorizeShare(data).getBoolean("success")&&g.focuses.isEmpty(),"share accepted body in Root metadata");SystemClock.time=6000;check(!g.host.authorizeShare(request().metadata()).getBoolean("success"),"expired share lease authorized");});
  test("time consumed inside fresh state/session lookups cannot authorize later side effects",()->{Fixture f=new Fixture();f.snapshotHook=()->SystemClock.time=6000;check(!f.prepare().getBoolean("success")&&f.focuses.isEmpty(),"expired snapshot focused target");SystemClock.time=1000;Fixture g=new Fixture();g.sessionHook=()->SystemClock.time=6000;check(!g.host.authorizeShare(request().metadata()).getBoolean("success")&&g.focuses.isEmpty(),"expired Provider lookup authorized share");});
  test("maintenance preserves an active edit but promptly retires newer input/reset without a callback",()->{Fixture f=new Fixture();f.prepare();check(f.host.maintain().getString("reason").equals("prepared")&&f.focuses.size()==1,"live edit prematurely restored");f.revision++;check(f.host.maintain().getString("reason").equals("newer_input_preserved")&&!f.host.hasCleanupResponsibility()&&f.focuses.size()==1,"orphaned edit blocked newer input");Fixture g=new Fixture();g.prepare();g.session=false;check(g.host.maintain().getString("reason").equals("session_ended")&&!g.host.hasCleanupResponsibility()&&g.focuses.size()==1,"old reset lease retained authority");});
  test("optional hook unavailability is explicit and keeps focus cleanup responsibility",()->{Fixture f=new Fixture();f.queryFailure="editor_evidence_unavailable";Bundle p=f.prepare();check(!p.getBoolean("success")&&p.getString("reason").equals("editor_evidence_unavailable")&&f.host.hasCleanupResponsibility(),"optional capability failure hidden or leaked focus");check(f.release().getBoolean("focus_restored"),"unsupported Hook could not restore focus");});
  System.out.println("PASTE HOST RESULT "+cases+" cases; "+checks+" assertions");
 }
}'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--negative-controls", action="store_true")
    args = parser.parse_args()
    sources = dict(SOURCES)
    sources["ls/augment/com/TestPasteHost.java"] = TEST
    with tempfile.TemporaryDirectory(prefix="lsa-paste-host-") as directory:
        SUPPORT["compile_run"](Path(directory), sources, PRODUCTION, "ls.augment.com.TestPasteHost")
    if args.negative_controls:
        negatives(sources)


def negatives(sources):
    mutations = [
        ("workspace.inputRevision() != lease.ownedRevision || workspace.activeInputWindow() != lease.ownedWindow", "false", "newer input lost focus to old lease"),
        ("if (!target.matches(r))", "if (false)", "stale/foreign target accepted"),
        ("if (!success(restored) || !lease.ownershipKnown || lease.ownedWindow != lease.priorWindow)", "if (false)", "restore failure silently cleared lease"),
        ("if (seen.containsKey(r.id)) return result(false, \"request_consumed\", r, false);", "if (false) return result(false, \"request_consumed\", r, false);", "share request ID started twice or became paste"),
    ]
    original = (SUPPORT["SRC"] / "AtomicWorkbenchPasteHost.java").read_text(encoding="utf-8")
    for before, after, expected in mutations:
        assert original.count(before) == 1, before
        with tempfile.TemporaryDirectory(prefix="lsa-paste-host-negative-") as directory:
            work = Path(directory); files = []; all_sources = dict(sources)
            all_sources.update({"ls/augment/com/" + name: (SUPPORT["SRC"] / name).read_text(encoding="utf-8") for name in PRODUCTION})
            all_sources["ls/augment/com/AtomicWorkbenchPasteHost.java"] = original.replace(before, after)
            for name, text in all_sources.items():
                path = work / name; path.parent.mkdir(parents=True, exist_ok=True); path.write_text(text, encoding="utf-8"); files.append(str(path))
            compiled = subprocess.run([SUPPORT["JAVAC"], "-encoding", "UTF-8", "-d", str(work / "classes"), *files], capture_output=True, text=True, encoding="utf-8", env=SUPPORT["ENV"], timeout=30)
            if compiled.returncode: raise AssertionError(compiled.stdout + compiled.stderr)
            result = subprocess.run([SUPPORT["JAVA"], "-cp", str(work / "classes"), "ls.augment.com.TestPasteHost"], capture_output=True, text=True, encoding="utf-8", env=SUPPORT["ENV"], timeout=30)
            if result.returncode == 0 or expected not in result.stdout + result.stderr: raise AssertionError(result.stdout + result.stderr)
            print("PASS paste-host negative control: " + before)


if __name__ == "__main__":
    main()
